import{_ as t,o as a,c as i,a7 as s}from"./chunks/framework.BJyR0VjM.js";const p=JSON.parse('{"title":"Authlib Injector","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/authlib-injector.md","filePath":"documentation/authlib-injector.md"}'),r={name:"documentation/authlib-injector.md"};function o(n,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="authlib-injector" tabindex="-1">Authlib Injector <a class="header-anchor" href="#authlib-injector" aria-label="Permalink to “Authlib Injector”">​</a></h1><p>YggUtils uses <a href="https://github.com/yushijinhun/authlib-injector" target="_blank" rel="noreferrer">authlib-injector</a> to redirect Minecraft&#39;s authentication calls from Mojang&#39;s servers to your custom Yggdrasil backend.</p><h2 id="what-is-authlib-injector" tabindex="-1">What Is authlib-injector? <a class="header-anchor" href="#what-is-authlib-injector" aria-label="Permalink to “What Is authlib-injector?”">​</a></h2><p>authlib-injector is a Java agent that patches Minecraft&#39;s bundled <code>authlib</code> at runtime using bytecode manipulation. When attached to the JVM via <code>-javaagent</code>, it intercepts all outgoing authentication requests and rewrites the target URL to point at your specified server instead of <code>sessionserver.mojang.com</code> and <code>authserver.mojang.com</code>.</p><h2 id="automatic-download" tabindex="-1">Automatic Download <a class="header-anchor" href="#automatic-download" aria-label="Permalink to “Automatic Download”">​</a></h2><p>YggUtils downloads authlib-injector automatically on first run if it isn&#39;t already present. It is saved to:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>meta/authlibinjector.jar</span></span></code></pre></div><p>The version bundled is fixed in YggUtils&#39;s source. If you need a specific version, you can manually place the correct JAR at <code>meta/authlibinjector.jar</code> before running — YggUtils will skip the download if the file already exists.</p><h2 id="how-it-is-attached" tabindex="-1">How It Is Attached <a class="header-anchor" href="#how-it-is-attached" aria-label="Permalink to “How It Is Attached”">​</a></h2><p>YggUtils passes authlib-injector to the server JVM using the standard Java agent flag:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-javaagent:meta/authlibinjector.jar=&lt;authserver&gt;</span></span></code></pre></div><p>The value after <code>=</code> is your <code>authserver</code> URL from <code>YggUtils.yml</code>. authlib-injector fetches the API metadata from this URL at server startup to configure itself.</p><h2 id="auth-server-requirements" tabindex="-1">Auth Server Requirements <a class="header-anchor" href="#auth-server-requirements" aria-label="Permalink to “Auth Server Requirements”">​</a></h2><p>Your authentication server must implement the Yggdrasil API and expose an API root that authlib-injector can query. Most self-hosted solutions (such as <a href="https://github.com/bs-community/blessing-skin-server" target="_blank" rel="noreferrer">blessing-skin-server</a> or similar) support this out of the box.</p><p>The <code>authserver</code> value in your config should be the root URL — for example:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://auth.example.com</span></span></code></pre></div><p>authlib-injector will append the necessary API paths itself.</p><h2 id="updating-authlib-injector" tabindex="-1">Updating authlib-injector <a class="header-anchor" href="#updating-authlib-injector" aria-label="Permalink to “Updating authlib-injector”">​</a></h2><p>To update to a newer version of authlib-injector, delete <code>meta/authlibinjector.jar</code> and update the download URL in YggUtils&#39;s source, then rebuild — or manually place the new JAR at that path.</p>',19)])])}const b=t(r,[["render",o]]);export{p as __pageData,b as default};
